-- Применять ПОСЛЕ деплоя кода (нужен блок photo-2017 и 2x2-цены checkbox).
-- Объединение услуг 2к17: single-photo-2017 = «Фото в стиле 2к17» на 1 или 2 человека; group-photo-2017 отключаем.
UPDATE "Service" SET
  "shortDesc" = $q$Реалистичное фото 1 или 2 человек в эстетике СНГ-2017$q$,
  "description" = $q$Загрузите одно или два фото — нейросеть перенесёт вас в атмосферу 2016–2017: двор, панельки, олимпийка или худи, малиновый закат и живой телефонный свет без мыльной AI-графики. Одно фото — один человек, два фото — двое друзей на одном кадре. По желанию оживим результат.$q$,
  "isActive" = true,
  "isFeatured" = true,
  "userInputForm" = $json$[{"id":"person1","type":"photo","label":"Фото 1 (обязательно)","required":true,"hint":"Чёткий портрет: лицо крупно и хорошо видно, примерно по грудь","maxSizeMb":10,"allowedFormats":["jpg","jpeg","png","webp"],"allowStudioAvatars":true,"allowSystemLibrary":false},{"id":"person2","type":"photo","label":"Фото 2 (необязательно)","required":false,"hint":"Добавьте второго человека — сделаем фото на двоих. Можно не добавлять.","maxSizeMb":10,"allowedFormats":["jpg","jpeg","png","webp"],"allowStudioAvatars":true,"allowSystemLibrary":false},{"id":"aspect","type":"aspect_ratio","label":"Формат кадра","required":false,"aspectOptions":["1:1","3:4","9:16","16:9"],"defaultAspect":"3:4"},{"id":"animate","type":"checkbox","label":"Анимировать фото (оживить)","required":false,"defaultChecked":false,"secondaryField":"person2","priceCoinsUnchecked":39,"priceCoinsChecked":99,"priceCoinsUncheckedSecondary":49,"priceCoinsCheckedSecondary":119,"hint":"Сначала создадим фото, затем Kling 3.0 мягко оживит его: камера медленно пролетает как в клипе, фон, ветер и свет двигаются, а вы просто смотрите в кадр. Результат — короткое видео."}]$json$::jsonb,
  "pipelineConfig" = $json$[{"id":"step_1","blockSlug":"photo-2017","input":"{{user.person1}}","params":{"model":{"standard":"gpt-image-2","pro":"gpt-image-2"},"image_urls":["{{user.person2}}"],"output_format":"jpg","aspect_ratio":"{{user.aspect}}","resolution":"4K","quality":"high","prompt_one":"GPT Image 2 edit. Use the uploaded photo ONLY as a face and identity reference. Reproduce the same person exactly and recognizably: same face shape, eyes, eyebrows, nose, mouth, jawline, hairstyle, hair color, skin tone, age and natural expression. Do NOT copy the original selfie pose, framing, clothing or background from the reference, and do NOT beautify, re-age or change the face.\n\nBuild a brand new authentic photo from the CIS / post-Soviet summer of 2016-2017, the nostalgic VK era. It must look like a real amateur phone snapshot taken by a friend from a few meters away, never a selfie.\n\nMANDATORY wardrobe change: replace whatever the person is wearing in the reference with authentic 2017 raion (двор) street style. Pick a believable combination: an adidas-style retro track jacket (олимпийка) with side stripes, OR a Thrasher-style flame-logo hoodie, OR a plain dark hoodie or tracksuit top; paired with dark tracksuit pants or fitted jeans and white sneakers; optionally a cap, beanie or small shoulder bag (барсетка). The outfit must clearly read as 2016-2017 CIS youth streetwear. Never keep the original clothing.\n\nScene: an ordinary post-Soviet courtyard at dusk. Grey panel apartment blocks (панельки / хрущёвки) in the background, asphalt, a bench, metal garages, workout bars (турники), old parked cars, a simple playground. Strong малиновый закат: a crimson-pink-purple sunset gradient sky glowing behind the buildings, warm low sunlight, long soft shadows.\n\nLIGHTING AND INTEGRATION (critical - this is the most important rule): the entire photo must share ONE single coherent light situation - the warm crimson-pink sunset light plus soft cool dusk ambient. The face and body MUST be fully re-lit and color-graded to match this exact light: a warm rim/edge light on the hair, cheek and shoulders coming from the glowing sky, soft warm-to-neutral fill on the face, and the SAME white balance, color temperature, exposure, contrast, softness and grain as the background. The person must look genuinely photographed standing in this courtyard at this moment, with their skin tone blended into the warm dusk grade while staying recognizable. Do NOT keep the original lighting or color of the reference face. Strictly avoid a pasted, cut-out, sticker or photoshop-composite look: the face must NOT be brighter, sharper, cleaner, cooler or a different color than the rest of the scene, and there must be no mismatch between the face and the environment.\n\nFraming and pose: a candid three-quarter shot framed from the head down to roughly the knees or mid-thigh - NOT a tiny distant full-body figure and NOT a tight face close-up. The person stands or leans casually in the yard against the sunset and the panelki, slightly off-center, relaxed and natural - hands in pockets or loosely at the sides, calm confident posture, looking at the camera or slightly away. Not a model pose, no outstretched arm, no phone in hand, no mirror.\n\nANATOMY AND PROPORTIONS (critical): render fully correct, natural human anatomy. The head must be in correct, realistic proportion to the neck and body, with normal shoulder width and natural limb and torso length. No oversized or undersized head, no shrunken or elongated body, no wrong head-to-body ratio, no warped or melted proportions, no distorted limbs or hands.\n\nLook and quality: this must look like a REAL amateur 2017 smartphone photo, not a polished studio render. Slightly soft focus, mild sensor noise and grain applied evenly across the WHOLE frame including the face, slightly uneven natural exposure, warm color cast, simple flat phone-camera depth (no fake bokeh), authentic imperfect VK vibe. Keep the FACE recognizable but lit and textured like the rest of the photo. Realistic skin texture, natural body proportions, correct hands.\n\nAvoid: disproportionate oversized or tiny head, wrong head-to-body ratio, elongated or shrunken body, warped or unnatural proportions, distorted limbs, pasted or cut-out faces, photoshop composite, sticker faces, faces lit differently from the scene, mismatched white balance or color temperature on the face, faces brighter sharper or cooler than the body and background, double lighting, glossy AI skin, beauty filter, glamour retouch, cinematic editorial polish, heavy HDR, oversaturation, selfie framing, close-up face crop, outstretched arm, phone or mirror in frame, modern influencer aesthetic, extra people, duplicated or distorted faces, deformed hands, text, captions, logos or watermarks.","prompt_two":"GPT Image 2 edit. You are given EXACTLY TWO reference images; each one is a separate real person. Create one new photorealistic photo of EXACTLY TWO people together from the CIS / post-Soviet summer of 2016-2017, the nostalgic VK era.\n\nCRITICAL identity and count rules:\n- Show EXACTLY TWO people and no one else: the first person comes from the first reference image, the second person from the second reference image.\n- Each person must be reproduced exactly and recognizably from their OWN reference image: same face shape, eyes, eyebrows, nose, mouth, jawline, hairstyle, hair color, skin tone, age and natural expression. Treat each reference as a distinct individual.\n- Do NOT blend, average, mix or swap faces between the two people. Do NOT duplicate either person, do NOT invent extra people, do NOT add background friends, crowds or faces on posters. Keep both faces sharp, clearly separated and recognizable.\n\nIt must look like a real amateur phone snapshot taken by a friend from a few meters away, never a selfie. The two stand or sit close together, relaxed and natural, in an ordinary post-Soviet courtyard at dusk.\n\nMANDATORY wardrobe change for both: replace whatever each person is wearing in their reference with authentic 2016-2017 raion (двор) street style - adidas-style retro track jackets (олимпийки) with side stripes, Thrasher-style flame-logo hoodies, plain dark hoodies or tracksuit tops, dark tracksuit pants or fitted jeans, white sneakers, optional caps or beanies. Vary the outfits naturally between the two. Never keep the original clothing.\n\nScene: grey panel apartment blocks (панельки / хрущёвки) in the background, asphalt, benches, metal garages, workout bars, old parked cars, a simple playground. Strong малиновый закат: a crimson-pink-purple sunset gradient sky glowing behind the buildings, warm low sunlight, long soft shadows.\n\nLIGHTING AND INTEGRATION (critical - this is the most important rule): the entire photo must share ONE single coherent light situation - the warm crimson-pink sunset light plus soft cool dusk ambient. EVERY face and body MUST be fully re-lit and color-graded to match this exact light: a warm rim/edge light on hair, cheeks and shoulders coming from the glowing sky, soft warm-to-neutral fill on the faces, and the SAME white balance, color temperature, exposure, contrast, softness and grain across both people and the background. Both must look genuinely photographed together standing in this courtyard at this moment, their skin tones blended into the warm dusk grade while staying recognizable. Do NOT keep the original lighting or color of the reference faces. Strictly avoid a pasted, cut-out, sticker or photoshop-composite look: neither face may be brighter, sharper, cleaner, cooler or a different color than the other or than the scene, and there must be no mismatch between faces and environment. Both people must be lit by the same single sunset light and sit in the same focal plane and grain.\n\nFraming and pose: a candid shot framed from the heads down to roughly the knees or mid-thigh - NOT tiny distant full-body figures and NOT tight face close-ups. The two stand or sit casually together against the sunset and the panelki, slightly off-center, relaxed natural posture, hands in pockets or loosely at the sides, looking at the camera or slightly away. Not model poses, no outstretched arm, no phone in hand, no mirror.\n\nANATOMY AND PROPORTIONS (critical): render fully correct, natural human anatomy for both. Each head must be in correct, realistic proportion to its neck and body, with normal shoulder width and natural limb and torso length, and both people at consistent, believable scale relative to each other. No oversized or undersized heads, no wrong head-to-body ratio, no shrunken or elongated bodies, no warped or melted proportions, no distorted limbs or hands.\n\nLook and quality: a REAL amateur 2017 smartphone photo, not a polished studio render. Slightly soft focus, mild sensor noise and grain applied evenly across the WHOLE frame including both faces, slightly uneven natural exposure, warm color cast, simple flat phone-camera depth, authentic imperfect VK vibe. Keep both FACES recognizable but lit and textured like the rest of the photo. Realistic skin texture, natural proportions, correct hands.\n\nAvoid: disproportionate oversized or tiny heads, wrong head-to-body ratio, elongated or shrunken bodies, inconsistent scale between the two, warped or unnatural proportions, distorted limbs, pasted or cut-out faces, photoshop composite, sticker faces, faces lit differently from the scene, mismatched white balance or color temperature on faces, faces brighter sharper or cooler than the bodies and background, double lighting, glossy AI skin, beauty filter, glamour retouch, cinematic editorial polish, heavy HDR, oversaturation, selfie framing, outstretched arm, phone or mirror in frame, modern influencer aesthetic, merged or duplicated faces, wrong number of people, distorted faces, deformed hands, text, captions, logos or watermarks.","animate":"{{user.animate}}","video_model":{"standard":"kling-3-pro","pro":"kling-3-pro"},"duration":5,"animation_prompt":"Bring this 2017 photo to life as a short, cinematic B-roll clip, like an establishing shot in a music video. The camera slowly drifts and glides past the scene with a smooth, steady slow dolly / parallax move, as if a videographer is filming a gentle fly-by. The person or people stay still and simply look calmly straight into the camera — almost no movement, only subtle micro-motion: slight natural blinking and faint breathing. Do NOT make them dance, gesture, walk, turn away or change pose or expression. The environment comes alive instead: wind gently moves their hair and clothes, trees, grass and bushes sway softly, the crimson-pink sunset clouds drift slowly, and the warm dusk light shimmers. Keep every face stable, sharp and exactly recognizable in every frame — no morphing, no identity drift, no face replacement, no warping of eyes, mouth or hands. Preserve the original composition, clothing, colours and the warm sunset lighting. Photorealistic, natural film-like motion, smooth, calm and steady."}}]$json$::jsonb
WHERE slug = $q$single-photo-2017$q$;

UPDATE "Service" SET "isActive" = false, "isFeatured" = false WHERE slug = $q$group-photo-2017$q$;
